def _status_from_response(r, net_info, url_probe, error_text, exception_text, http_status, response_text):
    if error_text is not None:
        return QueryStatus.UNKNOWN, (exception_text or error_text)
    if r is None:
        return QueryStatus.UNKNOWN, "No response"
    if any(sig in response_text for sig in _WAF):
        return QueryStatus.WAF, None

    error_type_list = normalize_error_type(net_info.get("errorType"))
    invalid = [e for e in error_type_list if e not in {"message", "status_code", "response_url"}]
    if invalid:
        return QueryStatus.UNKNOWN, f"Unknown error type: {invalid}"

    statuses = []

    if "message" in error_type_list:
        errors = net_info.get("errorMsg")
        flag = True
        if isinstance(errors, str):
            if errors in response_text:
                flag = False
        elif errors is not None:
            for e in errors:
                if e in response_text:
                    flag = False
                    break
        statuses.append(QueryStatus.CLAIMED if flag else QueryStatus.AVAILABLE)

    if "status_code" in error_type_list:
        codes = net_info.get("errorCode")
        sc = QueryStatus.CLAIMED
        if isinstance(codes, int):
            codes = [codes]
        if codes and http_status in codes:
            sc = QueryStatus.AVAILABLE
        elif isinstance(http_status, int) and (http_status < 200 or http_status >= 300):
            sc = QueryStatus.AVAILABLE
        statuses.append(sc)

    if "response_url" in error_type_list:
        final_url = getattr(r, "url", "")
        if isinstance(http_status, int) and 200 <= http_status < 300 and final_url == url_probe:
            statuses.append(QueryStatus.CLAIMED)
        else:
            statuses.append(QueryStatus.AVAILABLE)

    if not statuses:
        return QueryStatus.UNKNOWN, None
    if QueryStatus.AVAILABLE in statuses:
        return QueryStatus.AVAILABLE, None
    if QueryStatus.CLAIMED in statuses:
        return QueryStatus.CLAIMED, None
    return QueryStatus.UNKNOWN, None


def _run_search(sid, username, site_data, proxy, timeout_val):
    with _searches_lock:
        buf = _searches.get(sid)
    if buf is None:
        return

    sess = requests.Session()
    max_w = min(len(site_data), 50)
    fsess = SherlockFuturesSession(max_workers=max_w, session=sess)
    encoded = quote(username, safe="")
    futures_map = {}
    found = 0
    processed = 0

    try:
        for site_name, net_info in site_data.items():
            url_tpl = net_info.get("url")
            if not url_tpl:
                processed += 1
                with _searches_lock:
                    buf["processed"] = processed
                    buf["results"].append({"site": site_name, "url": "", "status": "Unknown", "found": False, "time_ms": None})
                continue

            url = interpolate_string(url_tpl, encoded)
            regex = net_info.get("regexCheck")
            if regex and re.search(regex, username) is None:
                processed += 1
                with _searches_lock:
                    buf["processed"] = processed
                    buf["results"].append({"site": site_name, "url": url, "status": "Illegal", "found": False, "time_ms": None})
                continue

            if not net_info.get("errorType"):
                processed += 1
                with _searches_lock:
                    buf["processed"] = processed
                    buf["results"].append({"site": site_name, "url": url, "status": "Unknown", "found": False, "time_ms": None})
                continue

            headers = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64; rv:129.0) Gecko/20100101 Firefox/129.0"}
            if isinstance(net_info.get("headers"), dict):
                headers.update(net_info["headers"])

            url_probe_raw = net_info.get("urlProbe")
            url_probe = interpolate_string(url_probe_raw, encoded) if url_probe_raw else url

            payload = net_info.get("request_payload")
            if payload:
                payload = interpolate_string(payload, username)

            error_type = net_info.get("errorType")
            req_fn = get_request_function(fsess, net_info.get("request_method"), error_type)
            norm = normalize_error_type(error_type)
            allow_redirects = "response_url" not in norm

            kw = {"url": url_probe, "headers": headers, "allow_redirects": allow_redirects, "timeout": timeout_val}
            if payload:
                kw["json"] = payload
            if proxy:
                kw["proxies"] = {"http": proxy, "https": proxy}

            future = req_fn(**kw)
            futures_map[future] = (site_name, net_info, url, url_probe)

        for future in concurrent.futures.as_completed(futures_map):
            site_name, net_info, url, url_probe = futures_map[future]
            r, error_text, exception_text = get_response(
                request_future=future,
                error_type=normalize_error_type(net_info.get("errorType")),
                social_network=site_name,
            )
            response_time = getattr(r, "sherlock_elapsed", None)
            http_status = getattr(r, "status_code", "?")
            response_text = getattr(r, "text", "") if r is not None else ""

            status, _ = _status_from_response(r, net_info, url_probe, error_text, exception_text, http_status, response_text)
            claimed = status == QueryStatus.CLAIMED
            if claimed:
                found += 1
            processed += 1

            with _searches_lock:
                buf["processed"] = processed
                buf["found"] = found
                if claimed:
                    buf["results"].append({
                        "site": site_name,
                        "url": url,
                        "status": status.value,
                        "found": True,
                        "time_ms": round(response_time * 1000) if response_time else None,
                    })

    except Exception as exc:
        with _searches_lock:
            buf["error"] = str(exc)
    finally:
        fsess.close()
        sess.close()
        found_sites = []
        with _searches_lock:
            buf["done"] = True
            buf["finished_at"] = time.time()
            found_sites = [r for r in buf["results"] if r.get("found")]

        with _history_lock:
            _history[:] = [h for h in _history if h["username"] != username]
            _history.insert(0, {
                "username": username,
                "count": found,
                "total": len(site_data),
                "sites": [{"site": r["site"], "url": r["url"]} for r in found_sites],
                "time": int(time.time() * 1000),
            })
            if len(_history) > 100:
                del _history[100:]

        threading.Timer(300, _cleanup_search, args=[sid]).start()


