@app.route("/api/search/start", methods=["GET", "POST"])
def search_start():
    raw_q = request.args.get("q", "").strip()
    proxy = request.args.get("proxy", "").strip() or None
    nsfw = request.args.get("nsfw", "false").lower() == "true"
    sites_param = request.args.get("sites", "").strip()

    try:
        timeout_val = float(request.args.get("timeout", "10"))
        if not (0 < timeout_val <= 120):
            timeout_val = 10.0
    except (ValueError, TypeError):
        timeout_val = 10.0

    if not raw_q or not re.match(r"^[\w.\-]{1,60}$", raw_q):
        return jsonify({"error": "Érvénytelen felhasználónév"}), 400

    if not _sites_ready.is_set():
        return jsonify({"error": "Webhelyek betöltése még folyamatban"}), 503

    if _sites_error:
        return jsonify({"error": _sites_error}), 500

    with _sites_lock:
        base = dict(_sites_all if nsfw else _sites_sfw)

    if sites_param:
        wanted = {s.strip() for s in sites_param.split(",") if s.strip()}
        base = {k: v for k, v in base.items() if k in wanted}

    if not base:
        return jsonify({"error": "Nincsenek keresendő webhelyek"}), 400

    sid = uuid.uuid4().hex[:12]
    buf = {
        "username": raw_q,
        "results": [],
        "done": False,
        "error": None,
        "found": 0,
        "processed": 0,
        "total": len(base),
        "started_at": time.time(),
        "finished_at": None,
    }
    with _searches_lock:
        _searches[sid] = buf

    threading.Thread(target=_run_search, args=[sid, raw_q, base, proxy, timeout_val], daemon=True).start()

    return jsonify({"search_id": sid, "total": len(base)})


