@app.route("/api/export")
def export():
    fmt = request.args.get("format", "csv").lower()
    username = request.args.get("username", "").strip()

    with _history_lock:
        item = next((h for h in _history if h["username"] == username), None)

    if item is None:
        return jsonify({"error": "Keresés nem található"}), 404

    sites = item.get("sites", [])

    if fmt == "csv":
        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow(["Felhasználónév", "Platform", "URL"])
        for s in sites:
            w.writerow([username, s["site"], s["url"]])
        buf.seek(0)
        return Response(
            buf.getvalue(),
            mimetype="text/csv",
            headers={"Content-Disposition": f"attachment; filename=sherlock_{username}.csv"},
        )

    if fmt == "txt":
        lines = "\n".join(f"{s['site']}: {s['url']}" for s in sites)
        body = f"Sherlock – @{username}\n{'=' * 40}\n{lines}\n"
        return Response(
            body,
            mimetype="text/plain",
            headers={"Content-Disposition": f"attachment; filename=sherlock_{username}.txt"},
        )

    if fmt == "xlsx":
        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Sherlock"
        ws.append(["Felhasználónév", "Platform", "URL"])
        for s in sites:
            ws.append([username, s["site"], s["url"]])
        buf = io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        return Response(
            buf.getvalue(),
            mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename=sherlock_{username}.xlsx"},
        )

    return jsonify({"error": "Ismeretlen formátum"}), 400


