def _validate_proxy(proxy_str: Optional[str]) -> Optional[str]:
    if not proxy_str:
        return None
    proxy_str = proxy_str.strip()
    if not proxy_str:
        return None
    try:
        parsed = urlparse(proxy_str)
        if parsed.scheme in PROXY_SCHEMES and parsed.netloc:
            return proxy_str
    except Exception:
        pass
    logger.warning(f"Invalid proxy format ignored: {proxy_str[:50]}")
    return None


def _sanitize_cell(value: Any) -> str:
    s = str(value) if value is not None else ""
    s = s.replace("\r", " ").replace("\n", " ")
    if s.startswith(("=", "+", "-", "@", "\t")):
        return "'" + s
    return s


def _extract_json_from_text(text: str) -> Optional[Dict]:
    text = text.strip()
    try:
        return json.loads(text)
    except (json.JSONDecodeError, ValueError):
        pass
    first_brace = text.find("{")
    if first_brace == -1:
        return None
    last_brace = text.rfind("}")
    if last_brace <= first_brace:
        return None
    candidate = text[first_brace : last_brace + 1]
    try:
        return json.loads(candidate)
    except (json.JSONDecodeError, ValueError):
        pass
    depth = 0
    in_string = False
    escape_next = False
    start = first_brace
    for i in range(first_brace, len(text)):
        c = text[i]
        if escape_next:
            escape_next = False
            continue
        if c == "\\" and in_string:
            escape_next = True
            continue
        if c == '"' and not escape_next:
            in_string = not in_string
            continue
        if in_string:
            continue
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                candidate = text[start : i + 1]
                try:
                    return json.loads(candidate)
                except (json.JSONDecodeError, ValueError):
                    return None
    return None


def safe_get_json_param(args_key: str, json_key: str, default: str = "") -> str:
    value = request.args.get(args_key)
    if value is not None:
        stripped = value.strip()
        return stripped if stripped else default
    try:
        data = request.get_json(silent=True)
        if data and isinstance(data, dict):
            raw = data.get(json_key)
            if raw is not None:
                converted = str(raw).strip()
                return converted if converted else default
    except Exception as exc:
        logger.debug(f"Failed to parse JSON param '{json_key}': {exc}")
    return default


def safe_normalize_error_type(error_type: Any) -> List[str]:
    if not error_type:
        return []
    try:
        from sherlock_project.sherlock import normalize_error_type
        result = normalize_error_type(error_type)
        if isinstance(result, list):
            return result
        return []
    except Exception as exc:
        logger.debug(f"normalize_error_type failed: {exc}")
        if isinstance(error_type, str):
            return [error_type]
        if isinstance(error_type, list):
            return [str(e) for e in error_type if e]
        return []


