def _status_from_response(
    r: Any,
    net_info: Dict,
    url_probe: str,
    error_text: str,
    exception_text: str,
    http_status: Any,
    response_text: str,
) -> Tuple[str, Optional[str]]:
    if error_text:
        return "UNKNOWN", exception_text or error_text

    if r is None:
        return "UNKNOWN", "No response received"

    response_snippet = response_text[:MAX_RESPONSE_SNIPPET]
    response_snippet_lower = response_snippet.lower()
    for sig in _WAF_SIGNATURES:
        if sig.lower() in response_snippet_lower:
            return "WAF", "WAF signature detected"

    error_type_list = safe_normalize_error_type(net_info.get("errorType"))
    if not error_type_list:
        return "UNKNOWN", "No error type defined"

    invalid_types = [e for e in error_type_list if e not in {"message", "status_code", "response_url"}]
    if invalid_types:
        return "UNKNOWN", f"Invalid error types: {invalid_types}"

    statuses: List[Tuple[str, Optional[str]]] = []

    if "message" in error_type_list:
        errors = net_info.get("errorMsg", [])
        flag = True
        if isinstance(errors, str):
            if errors:
                flag = errors not in response_snippet
        elif isinstance(errors, list):
            non_empty_errors = [e for e in errors if e]
            if non_empty_errors:
                flag = all(e not in response_snippet for e in non_empty_errors)
            else:
                flag = True
        statuses.append(("CLAIMED" if flag else "AVAILABLE", None))

    if "status_code" in error_type_list:
        codes = net_info.get("errorCode", [])
        if isinstance(codes, int):
            codes = [codes]
        elif not isinstance(codes, list):
            codes = []
        try:
            status_int = int(str(http_status)) if http_status not in ("?", None) else 0
        except (ValueError, TypeError):
            status_int = 0
        if codes and status_int in codes:
            sc = "AVAILABLE"
        elif 200 <= status_int < 300:
            sc = "CLAIMED"
        else:
            sc = "AVAILABLE"
        statuses.append((sc, None))

    if "response_url" in error_type_list:
        final_url = getattr(r, "url", "")
        try:
            status_int = int(str(http_status)) if http_status not in ("?", None) else 0
        except (ValueError, TypeError):
            status_int = 0
        if 200 <= status_int < 300 and final_url == url_probe:
            statuses.append(("CLAIMED", None))
        else:
            statuses.append(("AVAILABLE", None))

    if not statuses:
        return "UNKNOWN", "No status rules evaluated"

    status_values = [s[0] for s in statuses]
    if all(s == "CLAIMED" for s in status_values):
        return "CLAIMED", None
    if all(s == "AVAILABLE" for s in status_values):
        return "AVAILABLE", None
    return "UNKNOWN", "Conflicting status signals: " + ", ".join(status_values)


def ai_decision(
    username: str,
    results: List[Dict],
    email: Optional[str] = None,
    password: Optional[str] = None,
) -> Dict[str, Any]:
    found_str = "\n".join(
        [f"{r['site']}: {r['url']}" for r in results if r.get("found", False)]
    )
    if len(found_str) > MAX_FOUND_STR_LENGTH:
        found_str = found_str[:MAX_FOUND_STR_LENGTH]
    email_safe = str(email) if email else "N/A"
    password_safe = str(password) if password else "N/A"

    prompt = f"""Minimax M2.7 Coding Agent! Username: {username}
Sherlock results: {found_str}
Email/Pass: {email_safe}/{password_safe}
Task: 1. Correlations 2. Best login target 3. 2FA bypass plan
Output STRICT JSON only:
