            model=AI_MODEL,
            messages=[
                {"role": "system", "content": "Elite hacker AI investigator. Return ONLY valid JSON."},
                {"role": "user", "content": prompt},
            ],
            temperature=AI_TEMPERATURE,
            max_tokens=MAX_AI_TOKENS,
        )
        content = response.choices[0].message.content.strip()

        result = _extract_json_from_text(content)
        if result is None:
            result = {}

        if not isinstance(result, dict):
            result = {}

        required_keys = {"analysis", "action", "target_site", "totp_codes", "proxy"}
        for key in required_keys:
            if key not in result:
                if key == "analysis":
                    result[key] = "Analysis unavailable"
                elif key == "action":
                    result[key] = "skip"
                elif key == "target_site":
                    result[key] = ""
                elif key == "totp_codes":
                    result[key] = []
                elif key == "proxy":
                    result[key] = ""

        if not isinstance(result.get("totp_codes"), list):
            result["totp_codes"] = []
        result["totp_codes"] = [str(c) for c in result["totp_codes"] if c][:MAX_TOTP_CODES]

        valid_actions = {"login_gmail", "linkedin_scrape", "skip"}
        if result["action"] not in valid_actions:
            result["action"] = "skip"

        proxy_val = result.get("proxy", "")
        result["proxy"] = _validate_proxy(proxy_val) or ""

        return {
            "analysis": str(result.get("analysis", "Analysis unavailable")),
            "action": result["action"],
            "target_site": str(result.get("target_site", "")),
            "totp_codes": result["totp_codes"],
