async def scrape_with_cookies(site: str, cookies: List[Dict]) -> str:
    browser = None
    context = None
    try:
        parsed = urlparse(site)
        if not parsed.scheme:
            site = f""
            parsed = urlparse(site)
        if not parsed.netloc:
            site = f""
            parsed = urlparse(site)

        async with async_playwright() as p:
            browser = await p.chromium.launch(headless=True, timeout=BROWSER_TIMEOUT)
            context = await browser.new_context()
            domain_for_cookies = parsed.netloc
            if domain_for_cookies.startswith("www."):
                domain_for_cookies = domain_for_cookies[4:]

            normalized_cookies = []
            for cookie in cookies:
                nc = dict(cookie)
                if not nc.get("domain") or nc.get("domain") == ".google.com":
                    nc["domain"] = domain_for_cookies
                if not nc.get("path"):
                    nc["path"] = "/"
                normalized_cookies.append(nc)

            if normalized_cookies:
                await context.add_cookies(normalized_cookies)
            page = await context.new_page()
            page.set_default_timeout(SCRAPE_TIMEOUT)

            await page.goto(site, timeout=SCRAPE_TIMEOUT, wait_until="domcontentloaded")
            content = await page.content()

            try:
                if context is not None:
                    await context.close()
                context = None
            except Exception as exc:
                logger.debug(f"context close error in scrape: {exc}")
            try:
                if browser is not None:
                    await browser.close()
                browser = None
            except Exception as exc:
                logger.debug(f"browser close error in scrape: {exc}")

        content_clean = re.sub(
            r"<script\b[^>]*>[\s\S]*?<\/script>",
            "",
            content,
            flags=re.DOTALL | re.IGNORECASE,
        )
        content_clean = re.sub(r"<style\b[^>]*>[\s\S]*?<\/style>", "", content_clean, flags=re.DOTALL | re.IGNORECASE)
        content_trunc = content_clean[:MAX_CONTENT_TRUNCATE]

        domain_label = parsed.netloc or site
        prompt = f"""Parse {domain_label} HTML, extract personal data as JSON:
name, phone, location, email, bio. Return ONLY valid JSON.

HTML: {content_trunc}"""

        if len(prompt) > MAX_PROMPT_LENGTH:
            prompt = prompt[:MAX_PROMPT_LENGTH]

        loop = asyncio.get_running_loop()
        response = await loop.run_in_executor(
            None,
            lambda: client.chat.completions.create(
                model=AI_MODEL,
                messages=[{"role": "user", "content": prompt}],
                temperature=AI_SCRAPE_TEMPERATURE,
                max_tokens=1000,
            ),
        )

        ai_content = response.choices[0].message.content.strip()
        result = _extract_json_from_text(ai_content)
        if result is not None and isinstance(result, dict):
            return json.dumps(result)
        return '{"status": "no_data"}'

    except Exception as e:
        logger.error(f"Scraping failed for {site}: {e}")
        return '{"error": "scraping_failed"}'
    finally:
        try:
            if context is not None:
                await context.close()
        except Exception as exc:
            logger.debug(f"context close error in scrape finally: {exc}")
        try:
            if browser is not None:
                await browser.close()
        except Exception as exc:
            logger.debug(f"browser close error in scrape finally: {exc}")


def _run_search(
    sid: str,
    username: str,
    site_ Dict[str, Dict],
    proxy: Optional[str],
    timeout_val: float,
):
    if not site_
        return

    validated_proxy = _validate_proxy(proxy)
    fsess = None
    futures_map: Dict[Any, Tuple[str, Dict, str, str]] = {}
    found_count = 0
    processed_count = 0
    encoded = quote(username, safe="")

    with _searches_lock:
        if sid not in _searches:
            return

    worker_count = min(len(site_data), MAX_WORKERS_CAP)

    with safe_sherlock_session(worker_count) as (fsess_result, _):
        if not fsess_result:
            with _searches_lock:
                if sid in _searches:
                    _searches[sid]["error"] = "Sherlock initialization failed"
                    _searches[sid]["done"] = True
            return

        fsess = fsess_result

        try:
            for site_name, net_info in list(site_data.items()):
                with _searches_lock:
                    if sid not in _searches:
                        return

                url_template = net_info.get("url", "")
                if not url_template:
                    processed_count += 1
                    with _searches_lock:
                        if sid in _searches:
                            _searches[sid]["processed"] = processed_count
                            _searches[sid]["results"].append(
                                {
                                    "site": site_name,
                                    "url": "",
                                    "status": "NoURL",
                                    "found": False,
                                    "time_ms": None,
                                    "reason": "No URL template defined",
                                }
                            )
                    continue

                url = safe_interpolate_string(url_template, encoded)

                regex_check = net_info.get("regexCheck")
                if regex_check:
                    try:
                        if not re.search(regex_check, username):
                            processed_count += 1
                            with _searches_lock:
                                if sid in _searches:
                                    _searches[sid]["processed"] = processed_count
                                    _searches[sid]["results"].append(
                                        {
                                            "site": site_name,
                                            "url": url,
                                            "status": "RegexFail",
                                            "found": False,
                                            "time_ms": None,
                                            "reason": f"Username does not match regex: {regex_check}",
                                        }
                                    )
                            continue
                    except re.error as re_exc:
                        logger.warning(f"Invalid regex '{regex_check}' for {site_name}: {re_exc}")
                        processed_count += 1
                        with _searches_lock:
                            if sid in _searches:
                                _searches[sid]["processed"] = processed_count
                                _searches[sid]["results"].append(
                                    {
                                        "site": site_name,
                                        "url": url,
                                        "status": "InvalidRegex",
                                        "found": False,
                                        "time_ms": None,
                                        "reason": f"Invalid regex: {regex_check}",
                                    }
                                )
                        continue

                error_types = net_info.get("errorType")
                if not error_types:
                    processed_count += 1
                    with _searches_lock:
                        if sid in _searches:
                            _searches[sid]["processed"] = processed_count
                            _searches[sid]["results"].append(
                                {
                                    "site": site_name,
                                    "url": url,
                                    "status": "NoErrorType",
                                    "found": False,
                                    "time_ms": None,
                                    "reason": "No errorType defined in site data",
                                }
                            )
                    continue

                headers = {"User-Agent": USER_AGENT}
                custom_headers = net_info.get("headers", {})
                if isinstance(custom_headers, dict):
                    protected_keys = {"User-Agent"}
                    for k, v in custom_headers.items():
                        if k not in protected_keys:
                            headers[k] = v

                url_probe_raw = net_info.get("urlProbe", url_template)
                url_probe = safe_interpolate_string(url_probe_raw, encoded)

                payload_data = net_info.get("request_payload")
                request_kwargs: Dict[str, Any] = {
                    "url": url_probe,
                    "headers": headers,
                    "allow_redirects": True,
                    "timeout": timeout_val,
                }

                if payload_
                    if isinstance(payload_data, dict):
                        request_kwargs["json"] = payload_data
                    elif isinstance(payload_data, str):
                        interpolated = safe_interpolate_string(payload_data, username)
                        try:
                            parsed_payload = json.loads(interpolated)
                            if isinstance(parsed_payload, dict):
                                request_kwargs["json"] = parsed_payload
                            else:
                                request_kwargs["data"] = interpolated
                        except (json.JSONDecodeError, ValueError):
                            request_kwargs["data"] = interpolated
                    else:
                        request_kwargs["data"] = str(payload_data)

                if validated_proxy:
                    request_kwargs["proxies"] = {
                        "http": validated_proxy,
                        "https": validated_proxy,
                    }

                req_method = net_info.get("request_method", "GET")
                normalized_errors = safe_normalize_error_type(error_types)
                req_fn = safe_get_request_function(fsess, req_method, error_types)

                if not req_fn:
                    processed_count += 1
                    with _searches_lock:
                        if sid in _searches:
                            _searches[sid]["processed"] = processed_count
                            _searches[sid]["results"].append(
                                {
                                    "site": site_name,
                                    "url": url,
                                    "status": "NoRequestFn",
                                    "found": False,
                                    "time_ms": None,
                                    "reason": "Could not determine request function",
                                }
                            )
                    continue

                try:
                    future = req_fn(**request_kwargs)
                    futures_map[future] = (site_name, net_info, url, url_probe)
                except Exception as req_exc:
                    processed_count += 1
                    with _searches_lock:
                        if sid in _searches:
                            _searches[sid]["processed"] = processed_count
                            _searches[sid]["results"].append(
                                {
                                    "site": site_name,
                                    "url": url,
                                    "status": "RequestFailed",
                                    "found": False,
                                    "time_ms": None,
                                    "reason": f"Request submission failed: {str(req_exc)[:200]}",
                                }
                            )

                time.sleep(RATE_LIMIT_DELAY)

            futures_list = list(futures_map.keys())
            try:
                for future in concurrent.futures.as_completed(
                    futures_list, timeout=SEARCH_TIMEOUT
                ):
                    with _searches_lock:
                        if sid not in _searches:
                            break

                    site_name, net_info, url, url_probe = futures_map[future]

                    try:
                        r, error_text, exception_text = safe_get_response(
                            request_future=future,
                            error_type=safe_normalize_error_type(
                                net_info.get("errorType")
                            ),
                            social_network=site_name,
                        )
                    except Exception as resp_exc:
                        r = None
                        error_text = f"Response extraction failed: {str(resp_exc)[:200]}"
                        exception_text = None

                    response_time = getattr(r, "sherlock_elapsed", 0.0)
                    if not isinstance(response_time, (int, float)):
                        response_time = 0.0
                    http_status = getattr(r, "status_code", "?")
                    response_text = ""
                    if r is not None:
                        raw_text = getattr(r, "text", "")
                        if raw_text:
                            response_text = raw_text[:MAX_RESPONSE_TEXT]

                    status, reason = _status_from_response(
                        r,
                        net_info,
                        url_probe,
                        error_text or "",
                        exception_text or "",
                        http_status,
                        response_text,
                    )

                    is_claimed = status == "CLAIMED"
                    if is_claimed:
                        found_count += 1

                    time_ms: Optional[int] = None
                    if isinstance(response_time, (int, float)) and response_time > 0:
                        time_ms = int(response_time * 1000)

                    processed_count += 1
                    result_record: Dict[str, Any] = {
                        "site": site_name,
                        "url": url,
                        "status": status,
                        "found": is_claimed,
                        "time_ms": time_ms,
                    }
                    if status == "UNKNOWN" and reason:
                        result_record["reason"] = reason

                    with _searches_lock:
                        if sid in _searches:
                            search_buf = _searches[sid]
                            search_buf["processed"] = processed_count
                            search_buf["found"] = found_count
                            search_buf["results"].append(result_record)

            except FuturesTimeoutError:
                logger.warning(f"Search {sid} futures timed out after {SEARCH_TIMEOUT}s")
                for pending_future in futures_list:
                    if not pending_future.done():
                        pending_future.cancel()
            finally:
                futures_map.clear()

        except FuturesTimeoutError:
            logger.warning(f"Search {sid} timed out")
        except Exception as exc:
            logger.error(f"Search {sid} error: {exc}")
            with _searches_lock:
                if sid in _searches:
                    _searches[sid]["error"] = f"Search crashed: {str(exc)}"
        finally:
            with _searches_lock:
                if sid in _searches:
                    _searches[sid]["done"] = True
                    _searches[sid]["finished_at"] = time.time()
                    _searches[sid]["processed"] = processed_count
                    _searches[sid]["found"] = found_count

    found_sites = []
    with _searches_lock:
        if sid in _searches:
            found_sites = [
                r for r in _searches[sid]["results"] if r.get("found", False)
            ]

    with _history_lock:
        _history[:] = [h for h in _history if h["username"] != username]
        _history.insert(
            0,
            {
                "username": username,
                "count": found_count,
                "total": len(site_data),
                "sites": [
                    {"site": r["site"], "url": r["url"]} for r in found_sites
                ],
                "time": int(time.time() * 1000),
            },
        )
        while len(_history) > MAX_HISTORY:
            _history.pop()

    with _active_usernames_lock:
        _active_usernames.pop(username, None)

    threading.Timer(CLEANUP_DELAY, lambda s=sid: _cleanup_search(s)).start()


def _cleanup_search(sid: str):
    with _searches_lock:
        _searches.pop(sid, None)


